from pypdf import PdfReader

reader = PdfReader("sc100-blank.pdf")
fields = reader.get_fields()

if fields:
    for field_name, field_data in fields.items():
        print(f"Field: {field_name}")
else:
    print("No fields found or could not read fields.")

from pypdf import PdfReader

reader = PdfReader("sc100-blank.pdf")
fields = reader.get_fields()

for field_name, field_data in fields.items():
    if '/V' in field_data:
        print(f"Field: {field_name}, Value: {field_data['/V']}")
    if '/Opt' in field_data:
        print(f"Field: {field_name}, Options: {field_data['/Opt']}")
    if '/FT' in field_data and field_data['/FT'] == '/Btn':
        # It's a button/checkbox
        print(f"Field: {field_name} is a Button/Checkbox")
        # Try to find export values
        if '/AP' in field_data:
             print(f"  Appearance states: {field_data['/AP'].keys()}")

import fitz

doc = fitz.open("sc100-filled.pdf")
for page in doc:
    for field in page.widgets():
        if field.field_value:
            print(f"Field: {field.field_name}, Value: {field.field_value}")
